#!/bin/bash
# Generated by Claude Fable 5.1 (Anthropic), 2026-10-25 (night)
# Re-analyse an EXISTING synthetic session without re-running the application: static class analysis of the (built)
# workspace -> map onto the session -> model + extractor with source corroboration -> verify.
# Usage: tests/synth/reanalyze_synth.sh <descriptor.json> <session_id> [log_dir]     env: IMG (default fishwait28)
#        REANALYZE_CPUS=18,19 confines the static step (docker --cpuset-cpus) and the python steps (taskset) to those CPUs
#        (2026-10-26: re-analyses next to running synthetic validation runs stay off the app/observer cores).
set -u; cd "$(dirname "$0")/../.."
DESC=$1; S=$2; LD=${3:-$HOME/fish_traces/synth_runs}; mkdir -p "$LD"
IMG=${IMG:-autoware-dev-trt-a1000-fishwait28:latest}
NAME=$(python3 -c "import json,sys; print(json.load(open(sys.argv[1]))['name'])" "$DESC")
WS=$HOME/fish_synth/ws_$NAME; A=$HOME/fish_traces/analysis_$S; mkdir -p "$A"
[ -d "$WS/build" ] || { echo "[reanalyze] $WS has no build dir"; exit 2; }
CPUS=${REANALYZE_CPUS:-}; TS=${CPUS:+taskset -c $CPUS}
docker run --rm ${CPUS:+--cpuset-cpus "$CPUS"} --entrypoint bash -v "$WS":/ws -v "$PWD/scripts/source_flow":/sf:ro "$IMG" -c 'python3 /sf/source_flow.py --all --build /ws/build --src /ws/src --jobs 4 --out /ws/source_flow.json 2>&1 | tail -1'
$TS python3 scripts/source_flow/map_source_flow.py "$S" "$WS/source_flow.json" --out "$WS/flow_$S.json" > "$LD/map_$NAME.log" 2>&1 || { echo "[reanalyze] map failed"; exit 3; }
( cd postprocess && FISH_SOURCE_FLOW="$WS/flow_$S.json" $TS python3 model_improved_pg.py --session "$S" > "$A/model.log" 2>&1 && \
  FISH_SOURCE_FLOW="$WS/flow_$S.json" $TS python3 extract_fish_tasks.py "$S" -o "$A/fish_tasks.json" --releases "$A/releases.json" --show 6 > "$A/fish_tasks.txt" 2> "$A/fish_tasks.err" ) || { echo "[reanalyze] model / extractor failed (see $A/model.log, $A/fish_tasks.err)"; exit 4; }
$TS python3 tests/synth/verify_synth.py "$S" "$DESC" --tasks "$A/fish_tasks.json" | tee "$LD/verify_$NAME.txt"
